/**
 * Bureau data submission (Compliance → Bureau Submissions). The daily and
 * monthly SACRRA files are generated by the bureau crons, which the bake runs
 * every day (simulate/engine.ts plays the crons production leaves unscheduled)
 * in TEST mode (BUREAU_SUBMISSION_MODE=TEST: nothing is sent anywhere).
 *
 * A write-off (W) or attorney handover (L) is never listed on loan status
 * alone (lib/bureau-submission/.claude.md): the collections manager confirms
 * the listing with the date the consumer was given notice
 * (POST /api/compliance/bureau-submissions/adverse-confirmations). The notice
 * on file is the Section 129 notice; a written-off loan that never had one
 * stays unconfirmed and keeps reporting arrears only — the honest state.
 */
import { log } from "../sim/env"
import { readDb } from "../sim/readonly-db"
import { beforeEnd, step, type Breadth } from "./context"

interface Candidate {
  id: string
  reference: string
  code: "W" | "L"
  notice: string | null
}

/** Loans awaiting an adverse confirmation, as the Bureau Submissions screen lists them. */
async function candidates(): Promise<Candidate[]> {
  return readDb().$queryRawUnsafe<Candidate[]>(`
    SELECT l.id, l.reference, c.code,
      (SELECT min((r.data->>'issuedAt')::timestamptz AT TIME ZONE 'Africa/Johannesburg')::date::text FROM "ComplianceRecord" r
        WHERE r.type = 'SECTION_129_NOTICE' AND r."referenceId" = l.id AND r.data->>'issuedAt' IS NOT NULL) AS notice
    FROM "Loan" l
    CROSS JOIN LATERAL (VALUES (CASE WHEN l.status = 'WRITTEN_OFF' THEN 'W'
      WHEN EXISTS (SELECT 1 FROM "AttorneyReferral" a WHERE a."loanId" = l.id) THEN 'L' END)) AS c(code)
    WHERE c.code IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM "BureauAdverseConfirmation" x WHERE x."loanId" = l.id AND x."statusCode" = c.code)
    ORDER BY l.reference`)
}

async function confirmListings(b: Breadth): Promise<void> {
  let confirmed = 0
  for (const c of await candidates()) {
    if (!c.notice) {
      log(`bureau: ${c.reference} (${c.code}) has no Section 129 notice on file; listing left unconfirmed`)
      continue
    }
    await b.sim.actors.loanAdmin.post("/api/compliance/bureau-submissions/adverse-confirmations", {
      loanId: c.id, statusCode: c.code, noticeDate: c.notice,
    }, { expect: [201] })
    confirmed++
  }
  log(`bureau: ${confirmed} adverse listing(s) confirmed`)
}

export function scheduleBureau(b: Breadth): void {
  for (const daysBefore of [20, 2]) {
    step(b, "bureau-adverse", `confirm-${daysBefore}`, beforeEnd(b, daysBefore), "15:50", () => confirmListings(b))
  }
}
